#define main OldFrozenPoleUnusedMain
#include "diagnose_scri_pole.cpp"
#undef main
#include "mesh/cubed_sphere/hermite_boundary_probe.hpp"
#include "z4c/hyperboloidal/reference_gauge.hpp"
Real Size(const h::Z4cRHS<Real>&r){Real value=std::max({std::abs(r.chi),std::abs(r.trace),std::abs(r.theta)});for(int i=0;i<3;++i){value=std::max(value,std::abs(r.lambda[i]));for(int j=0;j<3;++j)value=std::max({value,std::abs(r.metric[i][j]),std::abs(r.a[i][j])});}return value;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=4)throw std::runtime_error("checkpoint source_tag output.csv");auto snap=cubed_sphere::CompositeCheckpoint::Read(argv[1],argv[2]);if(!snap.wormhole_chart||snap.positive_storage!=2||snap.isotropic_reference)throw std::runtime_error("expected frozen Minkowski-reference log-chart wormhole");cubed_sphere::CompositeDifference grid(snap.mesh,4,snap.radial_interface_stencils);if(grid.active.size()>50000)throw std::runtime_error("bounded50000");cubed_sphere::ScriSurface surface(grid,22,snap.scri_radial_points);V padded(22*grid.count,0);for(size_t p=0;p<grid.active.size();++p)for(int f=0;f<22;++f)padded[f*grid.count+grid.active[p]]=snap.fields[p*22+f];cubed_sphere::HermiteBoundaryProbe hermite(surface,padded,snap.boundary_fields,22);
 std::ofstream out(argv[3]);out<<std::setprecision(17)<<"row,face,j,k,x,y,z";const char*names[]={"chi","Khat","Theta","alpha","Axx","Axy","Axz","Ayy","Ayz","Azz","LambdaX","LambdaY","LambdaZ"};for(auto mode:{"original","Hermite"})for(auto name:names)out<<','<<mode<<'_'<<name;out<<'\n';Real old_max=0,new_max=0,old_component=0,new_component=0;size_t old_at=0,new_at=0;Real clock_tangent=0;
 for(size_t p=0;p<surface.rows.size();++p){const auto&row=surface.rows[p];const auto&x=row.geometry.x;const Real q[3]={1,(row.j+.5)/grid.n,(row.k+.5)/grid.n};out<<p<<','<<grid.mesh.blocks[row.block].face<<','<<row.j<<','<<row.k<<','<<x[0]<<','<<x[1]<<','<<x[2];for(int mode=0;mode<2;++mode){auto sampled=mode?hermite.At(row.block,q):cubed_sphere::CenteredSurfaceAtlas::Jets{};if(!mode){auto old=surface.Sample(p,padded,snap.boundary_fields,22);sampled.value=old.value;sampled.d=old.d;sampled.dd=old.dd;}auto u=h::UnpackComposite(x,sampled.value,sampled.d,sampled.dd,true,0,2);Real beta[3];if(!h::FixedAngleScriShift(h::Geometry(u.metric),Real(1),u.chi.value,x,beta))throw std::runtime_error("invalid fixed-angle null datum");for(int i=0;i<3;++i)u.beta.value[i]=beta[i];const auto pole=Poles(u,x);for(size_t f=0;f<pole.size();++f){out<<','<<pole[f];if(mode?std::abs(pole[f])>new_max:std::abs(pole[f])>old_max){if(mode){new_max=std::abs(pole[f]);new_at=p;new_component=f;}else{old_max=std::abs(pole[f]);old_at=p;old_component=f;}}}if(mode){Real normal=0;for(int i=0;i<3;++i)normal+=x[i]*u.alpha.d[i];for(int i=0;i<3;++i)clock_tangent=std::max(clock_tangent,std::abs(u.alpha.d[i]-normal*x[i]));}}out<<'\n';}
 // Complete tensor-limit equilibrium control: all stored deviations zero,
 // including independent Lambda and beta_delta. This is not native evolution.
 V minkowski_volume(22*grid.count,0),minkowski_boundary(surface.values.size(),0);cubed_sphere::HermiteBoundaryProbe minkowski(surface,minkowski_volume,minkowski_boundary,22);Real minkowski_pole=0,minkowski_limit=0,minkowski_clock=0,minkowski_constant=0;h::CMCReference<Real> reference{1,1};
 for(const auto&row:surface.rows){const auto&x=row.geometry.x;Real q[3]={1,(row.j+.5)/grid.n,(row.k+.5)/grid.n};const auto sample=minkowski.At(row.block,q);for(int f=0;f<22;++f){minkowski_constant=std::max(minkowski_constant,std::abs(sample.value[f]));for(int i=0;i<3;++i){minkowski_constant=std::max(minkowski_constant,std::abs(sample.d[f][i]));for(int j=0;j<3;++j)minkowski_constant=std::max(minkowski_constant,std::abs(sample.dd[f][i][j]));}}const auto u=h::UnpackComposite(x,sample.value,sample.d,sample.dd,true,0,2);const auto o=Omega(x,u);const auto parts=h::ConformalRHS(u,o,Real(4),Real(-.99),true);const auto normal=h::TensorPoleNormalJet(u,o,x,x,Real(4),Real(-.99),Real(1),Real(1),true,true);const auto rate=h::TensorScriLimit(parts.regular,normal,Real(-1));const auto gauge=h::UnfactoredReferenceGauge(reference,reference.At(x[0],x[1],x[2]),u,h::GaugeParameters<Real>{1,0,2,0},true,true);if(!parts.valid||!gauge.valid)throw std::runtime_error("Minkowski source invalid");minkowski_pole=std::max(minkowski_pole,Size(parts.pole));minkowski_limit=std::max(minkowski_limit,Size(rate));minkowski_clock=std::max(minkowski_clock,std::abs(gauge.regular.alpha-normal.lapse.derivative));}
 std::cout<<std::setprecision(17)<<"{\"time\":"<<snap.step*snap.dt<<",\"cells\":"<<grid.active.size()<<",\"rows\":"<<surface.rows.size()<<",\"radial_nodes\":"<<surface.radial_nodes<<",\"original_pole\":"<<old_max<<",\"original_row\":"<<old_at<<",\"original_component\":\""<<names[int(old_component)]<<"\",\"Hermite_pole\":"<<new_max<<",\"Hermite_row\":"<<new_at<<",\"Hermite_component\":\""<<names[int(new_component)]<<"\",\"clock_tangent_gradient\":"<<clock_tangent<<",\"Minkowski_stored_constant_jet\":"<<minkowski_constant<<",\"Minkowski_tensor_pole\":"<<minkowski_pole<<",\"Minkowski_tensor_limit\":"<<minkowski_limit<<",\"Minkowski_clock_rate\":"<<minkowski_clock<<",\"no_solve_or_evolution\":true,\"frozen_full_regular_limit_checked\":false}\n";if(minkowski_constant||minkowski_pole>1e-12||minkowski_limit>1e-12||minkowski_clock>1e-12||clock_tangent>1e-12)throw std::runtime_error("Hermite Minkowski/clock consistency failed");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
